<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import { LayoutDashboard, Users, Clock3, LogOut, ArrowUpRight, CalendarDays, Download, Plus, X, ChevronRight, BriefcaseBusiness, Menu, CheckCircle2, Settings } from 'lucide-vue-next';
const user=ref(null), records=ref([]), employees=ref([]), active=ref(null), page=ref('inicio'), loading=ref(true), busy=ref(false), error=ref(''), modal=ref(false), editing=ref(null), menu=ref(false);
const now=ref(Date.now()), todayRecords=ref([]), exportFilters=ref({from:'',to:'',employee_id:''});
let timer;
const recordPage=ref({data:[],current_page:1,last_page:1,total:0}), filters=ref({from:'',to:'',employee_id:''}), recordError=ref(''), correction=ref(null), correctionForm=ref({started_at:'',ended_at:'',reason:''}), history=ref(null);
const report=ref({employee_id:'',month:''}), company=ref({name:'',tax_id:'',address:'',email:'',phone:'',has_signature:false}), signatureFile=ref(null), removeSignature=ref(false), companyMessage=ref(''), companyError=ref(''), signatureVersion=ref(Date.now());
const login=ref({email:'',password:''});
const form=ref({name:'',email:'',password:'',position:'',identity_number:'',social_security_number:'',daily_hours:8,role:'employee',active:true});
const token=document.querySelector('meta[name="csrf-token"]').content;
async function request(url, options={}) { const response=await fetch(url,{credentials:'same-origin',...options,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':token,...options.headers}}); if (!response.ok) { let data=await response.json().catch(()=>({})); throw new Error(Object.values(data.errors || {}).flat()[0] || data.message || 'Ha ocurrido un error. Inténtalo de nuevo.'); } return response.json(); }
async function load(){ try { const data=await request('/api/state'); user.value=data.user; records.value=data.records; employees.value=data.employees; active.value=data.activeRecord; todayRecords.value=data.todayRecords; } catch(e) { user.value=null; } finally { loading.value=false; } }
async function signIn(){busy.value=true;error.value='';try{await request('/login',{method:'POST',body:JSON.stringify(login.value)}); location.reload();}catch(e){error.value=e.message}finally{busy.value=false}}
async function signOut(){await request('/logout',{method:'POST'});location.reload()}
async function clock(){busy.value=true;error.value='';try{await request('/api/clock',{method:'POST'});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
function openEmployee(employee=null){editing.value=employee?.id || null; form.value=employee ? {...employee,password:''} : {name:'',email:'',password:'',position:'',identity_number:'',social_security_number:'',daily_hours:8,role:'employee',active:true};error.value='';modal.value=true}
async function save(){busy.value=true;error.value='';try{await request(editing.value ? `/api/employees/${editing.value}` : '/api/employees',{method:editing.value?'PUT':'POST',body:JSON.stringify(form.value)});modal.value=false;await load()}catch(e){error.value=e.message}finally{busy.value=false}}
const admin=computed(()=>user.value?.role==='admin');
const date=computed(()=>new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(now.value))); 
const fmt=(v, opts={day:'2-digit',month:'short',year:'numeric'})=>v ? new Intl.DateTimeFormat('es-ES',opts).format(new Date(v)) : '—';
const time=v=>fmt(v,{hour:'2-digit',minute:'2-digit'});
const hours=r=>r.ended_at ? `${Math.floor((new Date(r.ended_at)-new Date(r.started_at))/3600000)}h ${String(Math.floor((new Date(r.ended_at)-new Date(r.started_at))/60000)%60).padStart(2,'0')}m` : 'En curso';
const totalToday=computed(()=>{const current=new Date(now.value); const start=new Date(current.getFullYear(),current.getMonth(),current.getDate()).getTime(); const ms=todayRecords.value.reduce((sum,r)=>sum+Math.max(0,Math.min(r.ended_at ? new Date(r.ended_at).getTime() : now.value,now.value)-Math.max(new Date(r.started_at).getTime(),start)),0); const seconds=Math.floor(ms/1000); return `${String(Math.floor(seconds/3600)).padStart(2,'0')}:${String(Math.floor(seconds/60)%60).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`});
const exportUrl=computed(()=>{const params=new URLSearchParams(Object.entries(exportFilters.value).filter(([,v])=>v));return '/api/export'+(params.size?'?'+params.toString():'')});
function queryString(values){return new URLSearchParams(Object.entries(values).filter(([,v])=>v!=='' && v!=null)).toString()}
async function loadRecords(p=1){recordError.value='';try{recordPage.value=await request('/api/records?'+queryString({...filters.value,page:p}))}catch(e){recordError.value=e.message}}
function go(p){page.value=p;menu.value=false;if(p==='registros')loadRecords();if(p==='laboral'){recordPage.value={data:[],current_page:1,last_page:1,total:0};recordError.value=''}if(p==='ajustes')loadCompany()}
function localInput(v){if(!v)return '';const d=new Date(v);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function editRecord(r){correction.value=r;correctionForm.value={started_at:localInput(r.started_at),ended_at:localInput(r.ended_at),reason:''};recordError.value=''}
async function saveCorrection(){busy.value=true;recordError.value='';try{await request(`/api/records/${correction.value.id}`,{method:'PUT',body:JSON.stringify(correctionForm.value)});correction.value=null;await Promise.all([load(),loadRecords(recordPage.value.current_page)])}catch(e){recordError.value=e.message}finally{busy.value=false}}
async function showHistory(r){recordError.value='';try{history.value={record:r,items:await request(`/api/records/${r.id}/history`)}}catch(e){recordError.value=e.message}}
const reportFilters=computed(()=>{if(!report.value.month)return {};const [year,month]=report.value.month.split('-').map(Number);const last=new Date(year,month,0).getDate();return {from:`${report.value.month}-01`,to:`${report.value.month}-${String(last).padStart(2,'0')}`,employee_id:admin.value?report.value.employee_id:''}});
const canPdf=computed(()=>report.value.month && (!admin.value || report.value.employee_id));
const pdfUrl=computed(()=>'/api/records/pdf?'+queryString(reportFilters.value));
async function loadReport(p=1){if(!canPdf.value)return;recordError.value='';try{recordPage.value=await request('/api/records?'+queryString({...reportFilters.value,page:p}))}catch(e){recordError.value=e.message}}
async function loadCompany(){companyError.value='';try{company.value=await request('/api/company-settings')}catch(e){companyError.value=e.message}}
async function saveCompany(){busy.value=true;companyMessage.value='';companyError.value='';try{const data=new FormData();for(const key of ['name','tax_id','address','email','phone'])data.append(key,company.value[key]||'');if(signatureFile.value)data.append('signature',signatureFile.value);if(removeSignature.value)data.append('remove_signature','1');const response=await fetch('/api/company-settings',{method:'POST',credentials:'same-origin',headers:{'Accept':'application/json','X-CSRF-TOKEN':token},body:data});const result=await response.json();if(!response.ok)throw new Error(Object.values(result.errors||{}).flat()[0]||result.message||'No se pudieron guardar los ajustes.');company.value=result;signatureFile.value=null;removeSignature.value=false;signatureVersion.value=Date.now();companyMessage.value='Datos guardados correctamente.'}catch(e){companyError.value=e.message}finally{busy.value=false}}

onMounted(()=>{load(); timer=setInterval(()=>{const before=new Date(now.value).toDateString(); now.value=Date.now(); if (new Date(now.value).toDateString()!==before && user.value) load()},1000)});
onUnmounted(()=>clearInterval(timer));
</script>
<template>
<div v-if="loading" class="loading">Preparando tu espacio…</div>
<div v-else-if="!user" class="login-page"><div class="login-aside"><div class="brand light"><span class="brand-icon">✳</span><span>mis fichajes<span class="brand-dot">.</span></span></div><div class="login-copy"><span class="eyebrow pale">TU TIEMPO, EN ORDEN</span><h1>El trabajo fluye<br>mejor cuando<br>cuentas con <em>claridad.</em></h1><p>Una forma más sencilla de registrar tu jornada y cuidar el tiempo de tu equipo.</p><div class="aside-art"><div class="art-clock">09<span>:</span>41 <small>AM</small></div><div class="art-line"></div><div class="art-label"><span class="online"></span> Todo bajo control <ArrowUpRight :size="18"/></div></div></div><div class="aside-footer">HECHO PARA EQUIPOS REALES <span>© MIS FICHAJES</span></div></div><div class="login-main"><div class="login-box"><span class="eyebrow">BIENVENIDO DE NUEVO</span><h2>Tu jornada empieza aquí<span class="accent">.</span></h2><p>Accede a tu espacio para gestionar tu tiempo.</p><form @submit.prevent="signIn"><label>Correo electrónico<input v-model="login.email" type="email" required placeholder="nombre@empresa.com" autocomplete="username"></label><label>Contraseña<input v-model="login.password" type="password" required placeholder="Introduce tu contraseña" autocomplete="current-password"></label><p v-if="error" class="error">{{ error }}</p><button class="primary wide" :disabled="busy">Entrar a mi espacio <ChevronRight :size="18"/></button></form><p class="login-help">¿Necesitas ayuda? Contacta con el administrador de tu empresa.</p></div><div class="login-bottom">Una jornada más sencilla empieza aquí. <span>✳</span></div></div></div>
<div v-else class="app-shell"><aside class="sidebar" :class="{open:menu}"><div class="brand"><span class="brand-icon">✳</span><span>mis fichajes<span class="brand-dot">.</span></span></div><div class="nav-label">MENÚ PRINCIPAL</div><nav><button :class="{selected:page==='inicio'}" @click="go('inicio')"><LayoutDashboard/> Resumen</button><button :class="{selected:page==='registros'}" @click="go('registros')"><Clock3/> Historial</button><button :class="{selected:page==='laboral'}" @click="go('laboral')"><CalendarDays/> Registro laboral</button><button v-if="admin" :class="{selected:page==='equipo'}" @click="go('equipo')"><Users/> Equipo</button><button v-if="admin" :class="{selected:page==='ajustes'}" @click="go('ajustes')"><Settings/> Ajustes</button></nav><div class="sidebar-bottom"><div class="sidebar-note"><span>✳</span><strong>Cada minuto cuenta.</strong><p>Haz espacio para lo que importa.</p></div><button class="profile" @click="signOut"><span class="avatar">{{ user.name.charAt(0).toUpperCase() }}</span><span><strong>{{ user.name }}</strong><small>{{ admin ? 'Administrador' : 'Empleado' }}</small></span><LogOut :size="17"/></button></div></aside><main class="main"><header class="topbar"><button class="mobile-menu" @click="menu=!menu"><Menu/></button><div class="breadcrumb">Mi espacio <ChevronRight :size="14"/> <strong>{{ page==='inicio'?'Resumen':page==='equipo'?'Equipo':page==='ajustes'?'Ajustes':page==='laboral'?'Registro laboral':'Historial' }}</strong></div><div class="top-right"><span class="today-chip"><CalendarDays :size="15"/> {{ date }}</span><span class="avatar small">{{ user.name.charAt(0).toUpperCase() }}</span></div></header><div class="content"><template v-if="page==='inicio'"><div class="heading"><div><span class="eyebrow">TU ESPACIO DE TRABAJO</span><h1>Hola, {{ user.name.split(' ')[0] }} <span class="wave">✳</span></h1><p>Todo lo que necesitas para llevar tu jornada al día.</p></div><span class="date-pill">{{ date }}</span></div><div v-if="error" class="error">{{ error }}</div><div class="overview"><div class="hero-card"><div class="hero-top"><span class="eyebrow pale">TU JORNADA DE HOY</span><span class="status"><span class="online"></span>{{ active ? 'Jornada en curso' : 'Fuera de jornada' }}</span></div><h2>{{ active ? 'Ya estás en marcha.' : 'Es hora de empezar.' }}</h2><p>{{ active ? 'Tu tiempo se está registrando. Que tengas una buena jornada.' : 'Cuando estés preparado, registra el inicio de tu jornada.' }}</p><div class="hero-bottom"><button class="clock-button" :class="{'clock-out':active}" :disabled="busy" @click="clock"><span>{{ active ? '↗' : '↘' }}</span> {{ active ? 'Finalizar jornada' : 'Fichar entrada' }} <ArrowUpRight :size="18"/></button><div class="hero-time"><small>TIEMPO DE HOY</small><strong>{{ totalToday }}</strong><small v-if="active">ENTRADA: {{ time(active.started_at) }}</small></div></div><div class="hero-decoration">✳</div></div><div class="side-stats"><div class="stat-card"><div class="stat-icon mint"><Clock3/></div><span>Tiempo registrado hoy</span><strong>{{ totalToday }}</strong><small>Tu actividad de hoy</small></div><div class="stat-card"><div class="stat-icon peach"><BriefcaseBusiness/></div><span>{{ admin ? 'Personas en el equipo' : 'Jornada diaria' }}</span><strong>{{ admin ? employees.filter(e=>e.active).length : user.daily_hours + ' h' }}</strong><small>{{ admin ? 'Cuentas activas' : 'Horas configuradas' }}</small></div></div></div><div class="section-head"><div><span class="eyebrow">TU ACTIVIDAD</span><h2>Últimos registros</h2><p>Un vistazo a {{ admin ? 'la actividad del equipo' : 'tus movimientos recientes' }}.</p></div><button class="text-button" @click="go('registros')">Ver todos <ArrowUpRight :size="16"/></button></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th v-if="admin">PERSONA</th><th>FECHA</th><th>ENTRADA</th><th>SALIDA</th><th>TIEMPO</th><th>ESTADO</th></tr></thead><tbody><tr v-for="r in records.slice(0,5)" :key="r.id"><td v-if="admin"><span class="person"><span class="avatar tiny">{{ r.user.name.charAt(0) }}</span>{{ r.user.name }}</span></td><td>{{ fmt(r.started_at) }}</td><td>{{ time(r.started_at) }}</td><td>{{ time(r.ended_at) }}</td><td>{{ hours(r) }}</td><td><span class="badge" :class="{live:!r.ended_at}">{{ r.ended_at ? 'Completado' : 'En curso' }}</span></td></tr></tbody></table><div v-if="!records.length" class="empty">Aún no hay registros. Tu actividad aparecerá aquí.</div></div></div></template><template v-else-if="page==='registros'"><div class="heading"><div><span class="eyebrow">{{ page==='laboral' ? 'INFORMES Y DESCARGAS' : 'HISTORIAL DE ACTIVIDAD' }}</span><h1>{{ page==='laboral' ? 'Registro laboral' : 'Historial' }}<span class="accent">.</span></h1><p>{{ page==='laboral' ? 'Prepara y descarga el informe de jornada para el período que necesites.' : 'Consulta y revisa las jornadas registradas.' }}</p></div></div><div class="table-card"><div class="table-title"><div><strong>{{ page==='laboral' ? 'Preparar informe' : 'Buscar fichajes' }}</strong><p>Filtra por fecha de entrada{{ admin ? ' y persona' : '' }}.</p></div></div><form class="export-filters" @submit.prevent="loadRecords(1)"><label>Desde<input type="date" v-model="filters.from" :max="filters.to || undefined"></label><label>Hasta<input type="date" v-model="filters.to" :min="filters.from || undefined"></label><label v-if="admin">Persona<select v-model="filters.employee_id"><option value="">Todo el equipo</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><button class="primary">Buscar</button><a v-if="admin && page==='laboral'" class="outline" :href="'/api/export?'+queryString(filters)"><Download :size="17"/> CSV</a><a v-if="page==='laboral' && canPdf" class="outline" :href="pdfUrl"><Download :size="17"/> Descargar PDF</a></form><p v-if="page==='laboral'" class="report-hint">Para descargar el PDF selecciona las dos fechas{{ admin ? ' y una persona' : '' }}. Los filtros se aplican a la fecha de entrada.</p><p v-if="recordError && !correction && !history" class="error">{{ recordError }}</p><div class="table-title"><div><strong>Historial de fichajes</strong><p>{{ recordPage.total }} registros encontrados</p></div></div><div class="table-wrap"><table><thead><tr><th v-if="admin">PERSONA</th><th>FECHA</th><th>ENTRADA</th><th>SALIDA</th><th>TIEMPO</th><th>ESTADO</th><th v-if="admin">ACCIONES</th></tr></thead><tbody><tr v-for="r in recordPage.data" :key="r.id"><td v-if="admin">{{ r.user.name }}</td><td>{{ fmt(r.started_at) }}</td><td>{{ time(r.started_at) }}</td><td>{{ r.ended_at ? fmt(r.ended_at)+' '+time(r.ended_at) : '—' }}</td><td>{{ hours(r) }}</td><td><span class="badge" :class="{live:!r.ended_at}">{{ r.ended_at ? 'Completado' : 'En curso' }}</span></td><td v-if="admin"><div class="record-actions"><button class="text-button" @click="editRecord(r)">Corregir</button><button class="text-button" @click="showHistory(r)">Historial</button></div></td></tr></tbody></table><div v-if="!recordPage.data.length" class="empty">No hay fichajes para los filtros seleccionados.</div></div><div class="pagination"><button class="outline" :disabled="recordPage.current_page<=1" @click="loadRecords(recordPage.current_page-1)">Anterior</button><span>Página {{ recordPage.current_page }} de {{ recordPage.last_page }}</span><button class="outline" :disabled="recordPage.current_page>=recordPage.last_page" @click="loadRecords(recordPage.current_page+1)">Siguiente</button></div></div></template><template v-else-if="page==='laboral'"><div class="heading"><div><span class="eyebrow">INFORMES Y DESCARGAS</span><h1>Registro laboral<span class="accent">.</span></h1><p>Selecciona un mes para consultar y descargar el informe de jornada.</p></div></div><div class="table-card"><div class="table-title"><div><strong>Preparar informe mensual</strong><p>El informe incluye los fichajes cuya entrada está dentro del mes elegido.</p></div></div><form class="export-filters" @submit.prevent="loadReport(1)"><label v-if="admin">Empleado<select v-model="report.employee_id" @change="recordPage={data:[],current_page:1,last_page:1,total:0}" required><option value="" disabled>Selecciona un empleado</option><option v-for="e in employees" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label v-else>Empleado<input :value="user.name" disabled></label><label>Mes<input type="month" v-model="report.month" @change="recordPage={data:[],current_page:1,last_page:1,total:0}" required></label><button class="primary">Consultar</button><a v-if="canPdf" class="outline" :href="pdfUrl"><Download :size="17"/> Descargar PDF</a><a v-if="admin && canPdf" class="outline" :href="'/api/export?'+queryString(reportFilters)"><Download :size="17"/> CSV</a></form><p v-if="recordError" class="error">{{ recordError }}</p><div class="table-title"><div><strong>Fichajes del mes</strong><p>{{ recordPage.total }} registros encontrados</p></div></div><div class="table-wrap"><table><thead><tr><th>FECHA</th><th>ENTRADA</th><th>SALIDA</th><th>TIEMPO</th><th>ESTADO</th></tr></thead><tbody><tr v-for="r in recordPage.data" :key="r.id"><td>{{ fmt(r.started_at) }}</td><td>{{ time(r.started_at) }}</td><td>{{ r.ended_at ? fmt(r.ended_at)+' '+time(r.ended_at) : '—' }}</td><td>{{ hours(r) }}</td><td><span class="badge" :class="{live:!r.ended_at}">{{ r.ended_at?'Completado':'En curso' }}</span></td></tr></tbody></table><div v-if="!recordPage.data.length" class="empty">Selecciona un empleado y un mes, y pulsa Consultar.</div></div><div class="pagination"><button class="outline" :disabled="recordPage.current_page<=1" @click="loadReport(recordPage.current_page-1)">Anterior</button><span>Página {{ recordPage.current_page }} de {{ recordPage.last_page }}</span><button class="outline" :disabled="recordPage.current_page>=recordPage.last_page" @click="loadReport(recordPage.current_page+1)">Siguiente</button></div></div></template><template v-else-if="page==='ajustes' && admin"><div class="heading"><div><span class="eyebrow">CONFIGURACIÓN</span><h1>Ajustes<span class="accent">.</span></h1><p>Gestiona los datos de empresa que aparecerán en los informes.</p></div></div><form class="table-card settings-form" @submit.prevent="saveCompany"><div class="settings-heading"><strong>Datos de la empresa</strong><p>Esta información se incluirá en el registro laboral.</p></div><div class="form-grid"><label>Nombre o razón social<input v-model="company.name" maxlength="255" placeholder="Nombre de la empresa"></label><label>CIF / NIF<input v-model="company.tax_id" maxlength="50" placeholder="Identificación fiscal"></label><label>Dirección<input v-model="company.address" maxlength="255" placeholder="Dirección fiscal"></label><label>Correo electrónico<input v-model="company.email" type="email" maxlength="255" placeholder="empresa@ejemplo.com"></label><label>Teléfono<input v-model="company.phone" maxlength="50" placeholder="Teléfono de contacto"></label></div><div class="signature-section"><strong>Firma de la empresa</strong><p>Se mostrará en los informes PDF. Formatos PNG o JPG, hasta 2 MB.</p><img v-if="company.has_signature && !removeSignature && !signatureFile" :src="'/api/company-settings/signature?v='+signatureVersion" alt="Firma actual de la empresa" class="signature-preview"><label>Subir firma<input type="file" accept="image/png,image/jpeg" @change="signatureFile=$event.target.files[0] || null; removeSignature=false"></label><label v-if="company.has_signature" class="check"><input type="checkbox" v-model="removeSignature" @change="signatureFile=null"> Eliminar firma actual</label></div><p v-if="companyError" class="error">{{ companyError }}</p><p v-if="companyMessage" class="settings-success">{{ companyMessage }}</p><div class="modal-actions"><button class="primary" :disabled="busy">Guardar ajustes</button></div></form></template><template v-else><div class="heading"><div><span class="eyebrow">LAS PERSONAS PRIMERO</span><h1>Tu equipo<span class="accent">.</span></h1><p>Gestiona las personas que forman parte de tu espacio.</p></div><button class="primary" @click="openEmployee()"><Plus :size="18"/> Añadir persona</button></div><div class="table-card"><div class="table-title"><div><strong>Personas del equipo</strong><p>Administra sus datos y acceso</p></div><span class="count">{{ employees.length }} personas</span></div><div class="table-wrap"><table><thead><tr><th>PERSONA</th><th>PUESTO</th><th>JORNADA</th><th>ACCESO</th><th>ESTADO</th><th></th></tr></thead><tbody><tr v-for="e in employees" :key="e.id"><td><span class="person"><span class="avatar tiny">{{ e.name.charAt(0) }}</span><span><strong>{{ e.name }}</strong><small>{{ e.email }}</small></span></span></td><td>{{ e.position || '—' }}</td><td>{{ e.daily_hours }} h / día</td><td>{{ e.role==='admin'?'Administrador':'Empleado' }}</td><td><span class="badge" :class="{live:e.active}">{{ e.active?'Activo':'Inactivo' }}</span></td><td><button class="text-button" @click="openEmployee(e)">Editar</button></td></tr></tbody></table></div></div></template><footer>Tu tiempo importa. <span>© Mis Fichajes</span></footer></div></main></div>
<div v-if="correction" class="modal-backdrop" @click.self="correction=null"><div class="modal"><div class="modal-head"><div><span class="eyebrow">REGISTRO LABORAL</span><h2>Corregir fichaje</h2><p class="report-hint">{{ correction.user.name }} · La modificación quedará registrada.</p></div><button class="icon-button" @click="correction=null"><X/></button></div><form @submit.prevent="saveCorrection"><div class="form-grid"><label>Entrada<input type="datetime-local" v-model="correctionForm.started_at" required></label><label>Salida (vacía si sigue en curso)<input type="datetime-local" v-model="correctionForm.ended_at"></label></div><label class="reason-label">Motivo de la corrección<textarea v-model="correctionForm.reason" minlength="5" maxlength="1000" required placeholder="Explica el motivo de este cambio"></textarea></label><p v-if="recordError" class="error">{{ recordError }}</p><div class="modal-actions"><button type="button" class="outline" @click="correction=null">Cancelar</button><button class="primary" :disabled="busy">Guardar corrección</button></div></form></div></div><div v-if="history" class="modal-backdrop" @click.self="history=null"><div class="modal"><div class="modal-head"><div><span class="eyebrow">TRAZABILIDAD</span><h2>Historial de cambios</h2><p class="report-hint">{{ history.record.user.name }}</p></div><button class="icon-button" @click="history=null"><X/></button></div><div v-if="!history.items.length" class="empty">Este fichaje todavía no tiene correcciones.</div><div v-for="change in history.items" :key="change.id" class="history-item"><strong>{{ change.actor_name }} · {{ fmt(change.created_at) }} {{ time(change.created_at) }}</strong><p>{{ change.reason }}</p><small>Antes: {{ change.previous_started_at }} — {{ change.previous_ended_at || 'En curso' }}</small><small>Después: {{ change.new_started_at }} — {{ change.new_ended_at || 'En curso' }}</small></div></div></div><div v-if="modal" class="modal-backdrop" @click.self="modal=false"><div class="modal"><div class="modal-head"><div><span class="eyebrow">EQUIPO</span><h2>{{ editing?'Editar persona':'Añadir persona' }}</h2></div><button class="icon-button" @click="modal=false"><X/></button></div><form @submit.prevent="save"><div class="form-grid"><label>Nombre completo<input v-model="form.name" required></label><label>Correo electrónico<input v-model="form.email" type="email" required></label><label>Contraseña {{ editing?'(dejar vacía para mantener)':'' }}<input v-model="form.password" type="password" :required="!editing" minlength="8"></label><label>Puesto<input v-model="form.position"></label><label>NIF / NIE<input v-model="form.identity_number" maxlength="50"></label><label>Nº afiliación Seguridad Social<input v-model="form.social_security_number" maxlength="50"></label><label>Horas diarias<input v-model="form.daily_hours" type="number" min="0" max="24" step="0.25" required></label><label>Acceso<select v-model="form.role"><option value="employee">Empleado</option><option value="admin">Administrador</option></select></label></div><label class="check"><input v-model="form.active" type="checkbox"> Cuenta activa</label><p v-if="error" class="error">{{ error }}</p><div class="modal-actions"><button type="button" class="outline" @click="modal=false">Cancelar</button><button class="primary" :disabled="busy"><CheckCircle2 :size="17"/> Guardar persona</button></div></form></div></div>
</template>
